# region imports
from AlgorithmImports import *
# endregion

class ETFUniverseSelectionAlgorithm(QCAlgorithm):
    _targets: list[PortfolioTarget] = []
    _weight: float = 0.33333333

    def initialize(self) -> None:
        self.set_start_date(2022, 1, 1)
        self.set_end_date(2024, 12, 31)
        self.set_cash(100000)
        self.settings.seed_initial_prices = True

        for ticker in {"SPY", "EFA", "EEM", "AGG", "GLD"}:
            symbol = self.add_equity(SecurityType.ETF, ticker).symbol
            self._targets.append(PortfolioTarget(symbol, self._weight))

        self.schedule.on(
            self.date_rules.month_start("SPY"),
            self.time_rules.at(9, 0),
            self._rebalance
        )

    def on_warmup_finished(self) -> None:
        self._rebalance()

    def on_order_event(self, order_event: OrderEvent) -> None:
        if order_event.status == OrderStatus.FILLED:
            self.plot("Fills", "SPY", order_event.fill_price * order_event.fill_quantity)

    def _rebalance(self) -> None:
        if not self._targets:
            return

        # Select the top 3 ETFs by 1-month return
        selected = sorted(
            self._targets,
            key=lambda target: self.securities[target.symbol].returns(1),
            reverse=True
        )[:3]

        # Remove securities that are not in the top 3
        for target in self._targets:
            if target.symbol not in [s.symbol for s in selected]:
                self.liquidate(target.symbol, tag=f"Remove {target.symbol}")

        # Reorder the remaining targets by fund weight
        self._targets = selected

        # Create the orders to rebalance the portfolio
        if not self.portfolio.invested:
            for target in self._targets:
                self.set_holdings(target, 1)

